/* Normalise la charge utile et deduit la pipeline TaxDome.
 * Le champ `resume` varie d'un simulateur a l'autre : on le conserve tel
 * quel, sans schema fige. */
const PIPELINES = {
  einkommensteuer: 'Einkommensteuererklärung',
  bescheidpruefung: 'Bescheidprüfung',
  lohnbuchhaltung: 'Lohnbuchhaltung',
  ustVoranmeldung: 'USt-Voranmeldung',
  fibu: 'Finanzbuchhaltung (FiBu)',
  jahresabschluss: 'Jahresabschluss / EÜR',
  existenzgruendung: 'Existenzgründung',
  onboarding: 'Mandanten-Onboarding',
};

return items.map((item) => {
  const c = item.json.body;
  const identifiants = c.outil?.pipelines || [];
  const pipelines = identifiants.map((id) => PIPELINES[id] || id);

  return {
    json: {
      recuLe: new Date().toISOString(),
      langue: c.langue,
      nom: c.contact.nom,
      email: c.contact.email,
      telephone: c.contact.telephone,
      message: c.contact.message,
      simulateur: c.outil?.id,
      pipelinePrincipale: pipelines[0] || 'Mandanten-Onboarding',
      pipelinesSecondaires: pipelines.slice(1),
      resume: c.resume,
      resumeLisible: Object.entries(c.resume || {})
        .map(([cle, valeur]) => `${cle} : ${valeur}`)
        .join('\n'),
      consentementTexte: c.consentement.texte,
      consentementHorodatage: c.consentement.horodatage,
      urlPage: c.contexte?.urlPage,
      versionContrat: c.version,
    },
  };
});

